export const isNumber=v=>typeof v==='number'&&Number.isFinite(v);
export function quantile(values,p){if(!values.length)return null;const a=[...values].sort((x,y)=>x-y),i=(a.length-1)*p,lo=Math.floor(i);return a[lo]+(a[Math.ceil(i)]-a[lo])*(i-lo)}
export function describe(rows){const v=rows.filter(r=>r.energy_eligible).map(r=>r.calculated_eui);return {n:v.length,min:v.length?Math.min(...v):null,q1:quantile(v,.25),median:quantile(v,.5),q3:quantile(v,.75),max:v.length?Math.max(...v):null}}
export function filterBuildings(rows,s){return rows.filter(r=>r.grain==='non_campus'&&(s.type==='all'||s.type==='focus'&&['Multifamily Housing','Office'].includes(r.type)||s.type===r.type)&&(!s.min||isNumber(r.area)&&r.area>=Number(s.min))&&(!s.max||isNumber(r.area)&&r.area<=Number(s.max))&&(!s.zip||r.zip===s.zip)&&(!s.status||r.status===s.status)&&(!s.query||[r.id,r.address,r.type,r.zip,...r.quality_flags].join(' ').toLowerCase().includes(s.query.toLowerCase())))}
export function scenario(rows,fraction){if(!Number.isFinite(fraction)||fraction<0||fraction>1)throw Error('Gap closure must be between 0 and 1');const eligible=rows.filter(r=>r.comparison_eligible);return {n:eligible.length,above:eligible.filter(r=>r.full_gap_kbtu>0).length,kbtu:eligible.length?eligible.reduce((s,r)=>s+r.full_gap_kbtu*fraction,0):null}}
export function sortRows(rows,key,direction='desc'){return [...rows].sort((a,b)=>{const x=a[key],y=b[key];if(x==null)return y==null?0:1;if(y==null)return -1;const cmp=typeof x==='number'?x-y:String(x).localeCompare(String(y));return direction==='asc'?cmp:-cmp})}
export const exportFields=['id','grain','campus_ids','address','address_source','zip','type','area','site_energy','reported_eui','calculated_eui','eui_difference','area_band','peer_n','peer_median','peer_q1','peer_q3','peer_percentile','relative_to_peer','estimated_emissions_tonnes','emissions_area','emissions_intensity','status','energy_eligible','comparison_eligible','investigation_candidate','full_gap_kbtu','energy_exclusions','emissions_exclusions','quality_flags','source_sheet','source_row','source_locations'];
export function csvText(rows,fraction){const fields=[...exportFields,...(fraction===undefined?[]:['selected_gap_closure_fraction','scenario_gap_kbtu'])];const cell=v=>{let x=v==null?'':Array.isArray(v)?JSON.stringify(v):String(v);if(/^[=+@]/.test(x))x="'"+x;return '"'+x.replaceAll('"','""')+'"'};return '\ufeff'+[fields.map(cell).join(','),...rows.map(r=>fields.map(f=>cell(f==='selected_gap_closure_fraction'?fraction:f==='scenario_gap_kbtu'?(r.comparison_eligible?r.full_gap_kbtu*fraction:null):r[f])).join(','))].join('\r\n')}
